script:
HIGH = 'High'

if doc.get('custom_risk_rating') == HIGH and not doc.get('custom_risk_review_date'):
    frappe.throw('Risk Review Date is required when Vendor Risk Rating is High.')

MIN_YEARS = 2
MIN_MONTHS = 3

state = doc.get('workflow_state') or ''
if state in ('Under Review', 'Approved'):
    est = doc.get('custom_establishment_date')
    if not est:
        frappe.throw('Establishment Date is required before review/approval.')
    today = frappe.utils.getdate(frappe.utils.today())
    years = (today - frappe.utils.getdate(est)).days / 365.0
    if years < MIN_YEARS:
        frappe.throw('Supplier must be in existence for at least ' + str(MIN_YEARS) + ' years.')

    months = frappe.utils.cint(doc.get('custom_product_availability_months') or 0)
    if months < MIN_MONTHS:
        frappe.throw('Product must be available in the civil market for at least ' + str(MIN_MONTHS) + ' months.')

    if doc.get('custom_is_sole_marketer') != 'Yes':
        frappe.throw('Supplier must be the sole marketer (set Is Sole Marketer to "Yes").')

REQUIRED = ("Turnover and sales certificate", "Factory location")
if doc.get('custom_document_type') in REQUIRED:
    if not doc.get('custom_file'):
        frappe.throw('Attachment required for ' + (doc.get('custom_document_type') or 'this document'))

# validation will block save if missing attachment.

REQUIRED = ("Turnover and sales certificate", "Factory location")
found = []
docs = doc.get('custom_supporting_documents') or []
for d in docs:
    dt = d.get('custom_document_type')
    f = d.get('custom_file')
    if dt in REQUIRED and f:
        if dt not in found:
            found.append(dt)
missing = []
for r in REQUIRED:
    if r not in found:
        missing.append(r)
if missing:
    frappe.throw('Please upload required supporting documents before saving: ' + ', '.join(missing))
else:
    # mark eligibility complete when the required supporting docs are present
    doc.custom_eligibility_complete = 1

MIN_TAX_ID_LEN = 6
MIN_BANK_ACCT_NO_LEN = 6
MIN_IBAN_LEN = 15
MAX_IBAN_LEN = 34

email = doc.get('email_id')
if email:
    ok = frappe.utils.validate_email_address(email, False)
    if not ok:
        frappe.throw('Email ID is not valid.')

website = doc.get('website')
if website:
    ok = frappe.utils.validate_url(website, False)
    if not ok:
        frappe.throw('Website URL is not valid.')

mobile = doc.get('mobile_no')
if mobile:
    ok = frappe.utils.validate_phone_number(mobile, False)
    if not ok:
        frappe.throw('Mobile number is not valid.')

upi = doc.get('custom_upi_id')
if upi:
    if ' ' in upi or '@' not in upi or len(upi) < 5:
        frappe.throw('UPI ID seems invalid. It should contain "@" and no spaces.')

tax_id = doc.get('tax_id')
if tax_id:
    if len(tax_id) < MIN_TAX_ID_LEN or not tax_id.replace(' ', '').isalnum():
        frappe.throw('Tax ID format looks invalid (min length and alphanumeric expected).')

def_bank = doc.get('default_bank_account')
if def_bank:
    values = frappe.db.get_value('Bank Account', def_bank, ['iban', 'bank_account_no'])
    iban_val = None
    bank_no_val = None
    if values:
        if isinstance(values, tuple):
            iban_val, bank_no_val = values[0], values[1]
        else:
            iban_val = values
    if not (iban_val or bank_no_val):
        frappe.throw('Default Bank Account must have either IBAN or Bank Account No.')
    if iban_val:
        if len(iban_val) < MIN_IBAN_LEN or len(iban_val) > MAX_IBAN_LEN:
            frappe.throw('IBAN length must be between ' + str(MIN_IBAN_LEN) + ' and ' + str(MAX_IBAN_LEN) + ' characters.')
    if bank_no_val:
        clean_no = bank_no_val.replace(' ', '')
        if len(clean_no) < MIN_BANK_ACCT_NO_LEN or not clean_no.isdigit():
            frappe.throw('Bank Account No must be numeric and at least ' + str(MIN_BANK_ACCT_NO_LEN) + ' digits.')

if doc.get('custom_document_type') == 'C-Form':
    if not doc.get('custom_c_form_number'):
        frappe.throw('C-Form Number is required for documents marked as C-Form.')
    if not doc.get('custom_document_file'):
        frappe.throw('Please attach the C-Form file in Document File for C-Form submissions.')
    if not doc.get('custom_c_form_received_date'):
        doc.custom_c_form_received_date = frappe.utils.today()
else:
    pass

if doc.get('custom_change_request_type') in ['New Introduction', 'Change Request']:
    docs = doc.get('custom_supplier_documents') or []
    if not docs or len(docs) == 0:
        frappe.throw('At least one Supporting Document must be attached for New Introduction or Change Request.')

TAX_ID_REQUIRED_COUNTRIES = ["India"]
BANK_TRANSFER_OPTIONS = ["Bank Transfer", "NEFT/RTGS"]
MIN_ELIGIBILITY_ROWS = 1
MIN_SUPPORTING_DOC_ROWS = 1

errors = []

today = frappe.utils.getdate(frappe.utils.nowdate())

if doc.get("custom_establishment_date"):
    if frappe.utils.getdate(doc.custom_establishment_date) > today:
        errors.append("Establishment Date cannot be in the future.")

if doc.get("country") and doc.country in TAX_ID_REQUIRED_COUNTRIES and not doc.get("tax_id"):
    errors.append("Tax ID is mandatory for suppliers in " + ", ".join(TAX_ID_REQUIRED_COUNTRIES) + ".")

ppm = doc.get("custom_preferred_payment_method")
if ppm:
    if ppm in BANK_TRANSFER_OPTIONS and not doc.get("default_bank_account"):
        errors.append("Default Bank Account is required when Preferred Payment Method is " + str(ppm) + ".")
    if "UPI" in ppm:
        upi = (doc.get("custom_upi_id") or "").strip()
        if not upi:
            errors.append("UPI ID is required when Preferred Payment Method is UPI.")
        else:
            if "@" not in upi or len(upi) < 5 or len(upi) > 45:
                errors.append("UPI ID appears invalid (expected format like name@bank).")

if doc.get("website"):
    w = doc.website.strip()
    if not (w.startswith("http://") or w.startswith("https://")):
        errors.append("Website URL must start with http:// or https://.")

if doc.get("email_id"):
    if not frappe.utils.validate_email_address(doc.email_id, False):
        errors.append("Primary Email appears invalid.")

if doc.get("mobile_no"):
    digits = "".join([c for c in doc.mobile_no if c.isdigit()])
    if len(digits) < 7:
        errors.append("Primary Mobile No. appears invalid.")

if doc.get("custom_risk_rating"):
    if not doc.get("custom_risk_review_date"):
        errors.append("Risk Review Date is required when Risk Rating is set.")
    else:
        if frappe.utils.getdate(doc.custom_risk_review_date) < today:
            errors.append("Risk Review Date cannot be in the past.")

elig = doc.get("custom_eligibility_criteria") or []
docs = doc.get("custom_supporting_documents") or []
if len(elig) < MIN_ELIGIBILITY_ROWS:
    errors.append("At least " + str(MIN_ELIGIBILITY_ROWS) + " Eligibility Criteria row(s) required.")
if len(docs) < MIN_SUPPORTING_DOC_ROWS:
    errors.append("At least " + str(MIN_SUPPORTING_DOC_ROWS) + " Supporting Document(s) required.")

if errors:
    doc.custom_eligibility_complete = 0
    doc.custom_csd_validation_summary = "CSD validation failed:\n- " + "\n- ".join(errors)
    frappe.throw("CSD validation failed. Please review the Validation Summary.")
else:
    doc.custom_eligibility_complete = 1
    doc.custom_csd_validation_summary = "All CSD checks passed on " + str(frappe.utils.formatdate(today)) + "."

if not doc.get('valid_from'):
    frappe.throw('Valid From (valid_from) is mandatory.')
if not doc.get('valid_to'):
    frappe.throw('Valid To (valid_to) is mandatory.')
if doc.get('valid_from') and doc.get('valid_to'):
    if frappe.utils.getdate(doc.valid_to) < frappe.utils.getdate(doc.valid_from):
        frappe.throw('Valid To (valid_to) must be the same or after Valid From (valid_from).')
if not doc.get('scheme_details') or not (doc.scheme_details or '').strip():
    frappe.throw('Scheme Details (scheme_details) is mandatory.')
if doc.get('custom_benefit_value') in (None, ''):
    frappe.throw('Benefit value (custom_benefit_value) is mandatory.')

for row in (doc.items or []):
    if not (row.generic_code or row.item):
        frappe.throw('Each product line must have either a Generic Code or an Item.')

SEEN_GENERIC_CODES = []
for row in (doc.items or []):
    code = row.generic_code
    if code:
        if code in SEEN_GENERIC_CODES:
            frappe.throw("Duplicate generic code '%s' in a single Supplier Product Registration is not allowed." % code)
        SEEN_GENERIC_CODES.append(code)

if doc.get('valid_from') and doc.get('valid_to'):
    if frappe.utils.getdate(doc.valid_to) < frappe.utils.getdate(doc.valid_from):
        frappe.throw('"Valid To" cannot be earlier than "Valid From"')

PREV_OWNER = None
PREV_STATE = None
PREV_ROLE = None
if doc.name:
    PREV_OWNER = frappe.db.get_value('Case', doc.name, 'current_owner')
    PREV_STATE = frappe.db.get_value('Case', doc.name, 'workflow_state')
    PREV_ROLE = frappe.db.get_value('Case', doc.name, 'custom_assigned_role')
owner_changed = False
role_changed = False
state_escalated = False
if (PREV_OWNER is None and doc.get('current_owner')) or (PREV_OWNER is not None and doc.get('current_owner') != PREV_OWNER):
    owner_changed = True
if (PREV_ROLE is None and doc.get('custom_assigned_role')) or (PREV_ROLE is not None and doc.get('custom_assigned_role') != PREV_ROLE):
    role_changed = True
if (PREV_STATE is None and doc.get('workflow_state') == 'Escalated') or (PREV_STATE is not None and doc.get('workflow_state') != PREV_STATE and doc.get('workflow_state') == 'Escalated'):
    state_escalated = True
if owner_changed or role_changed or state_escalated:
    mv = doc.append('movements', {})
    mv.moved_on = frappe.utils.now_datetime()
    mv.from_user = PREV_OWNER
    mv.to_user = doc.get('current_owner')
    if doc.get('custom_assigned_role'):
        mv.custom_to_role = doc.get('custom_assigned_role')
    if doc.get('assignment_remark'):
        mv.remark = doc.get('assignment_remark')
if doc.get('date_opened'):
    start = frappe.utils.getdate(doc.get('date_opened'))
    if doc.get('date_closed'):
        end = frappe.utils.getdate(doc.get('date_closed'))
    else:
        end = frappe.utils.getdate(frappe.utils.today())
    doc.custom_days_open = frappe.utils.date_diff(end, start)

if doc.custom_suspended==1:
  if not doc.custom_suspension_reason or str(doc.custom_suspension_reason).strip()=="":
    frappe.throw("Suspension Reason is required when Suspended is checked.")
else:
  pass

if doc.get('issue_type')=="Supplier":
  if not doc.get('custom_supplier'):
    frappe.throw("For supplier-related issues, Supplier must be set in the 'Supplier' field.")
else:
  pass

if doc.get('supplier_score'):
  doc.custom_supplier_score_numeric = frappe.utils.flt(doc.get('supplier_score'))
else:
  if not doc.get('custom_supplier_score_numeric'):
    doc.custom_supplier_score_numeric = 0.0

if True:
	# When status is set to 'Paid', ensure payment_reference exists and set paid_on if not present
	if doc.get('status') and str(doc.get('status')).lower() == 'paid':
		if not doc.get('payment_reference'):
			frappe.throw('Payment reference is required when status is Paid.')
		# set paid_on to today if not set
		if not doc.get('paid_on'):
			doc.paid_on = frappe.utils.nowdate()
	else:
		# no automatic clearing of paid_on for non-Paid statuses in this POC
		pass

if True:
	# Require at least one attachment field
	if not doc.get('file') and not doc.get('custom_file'):
		frappe.throw('An attachment is required on Supplier Document (file or custom_file).')
	# Enforce private files by checking the stored path contains "/private/" or 'private' prefix
	file_checked = False
	for f in ['file','custom_file']:
		val = doc.get(f)
		if val:
			if isinstance(val, str) and ('/private/' in val or val.startswith('private')):
				file_checked = True
			else:
				frappe.throw('Attached files must be private. Please upload via Private Files for ' + f + '.')
	if not file_checked:
		frappe.throw('No private attachment detected. Please upload files to private storage.')
	# Populate or normalize a DMS folder-path metadata field for hierarchical grouping in-ERP
	# Use the linked supplier name if available (custom_supplier) else leave generic
	supplier_name = doc.get('custom_supplier') or ''	
	doctype_label = doc.get('document_type') or 'Documents'
	if supplier_name:
		path = '/Suppliers/' + supplier_name + '/' + doctype_label + '/'
		doc.custom_dms_folder_path = path
	else:
		doc.custom_dms_folder_path = '/Suppliers/Unlinked/' + doctype_label + '/'

STATE_FORWARD_HO = "Forwarded to HO"
if doc.get("workflow_state") == STATE_FORWARD_HO:
    if not doc.get("custom_mstc_reference") or len(str(doc.get("custom_mstc_reference")).strip()) == 0:
        frappe.throw("MSTC Reference is required before forwarding to HO.")

if doc.get('custom_qd_release_date'):
    if not doc.get('custom_utilization_certificate'):
        frappe.throw('Attach Utilization Certificate before submitting a QD-released Material Request.')
    if not doc.get('custom_utilization_certificate_date'):
        frappe.throw('Utilization Certificate Date is required when QD Release Date is set.')
    amt = doc.get('custom_utilization_certificate_amount')
    if amt and amt < 0:
        frappe.throw('Utilization Amount cannot be negative.')

if doc.get('custom_depot'):
    # If supplier_warehouse not explicitly set, default it from depot selection
    if not doc.get('supplier_warehouse'):
        doc.supplier_warehouse = doc.get('custom_depot')
else:
    # no depot provided; do nothing
    pass

TITLE = 'Review Required'
if doc.get('customer'):
    if not doc.get('custom_lif_reviewed'):
        frappe.throw('LIF review is required before submit.')
    else:
        pass
    if not doc.get('custom_agm_secy_reviewed'):
        frappe.throw('AGM Secretariat review is required before submit.')
    else:
        pass
    if not doc.get('custom_cs_dir_reviewed'):
        frappe.throw('CS Directorate review is required before submit.')
    else:
        pass
else:
    pass

AUTO_CREATE_PO = True

if AUTO_CREATE_PO:
  if doc.get('custom_auto_create_po'):
    ws = doc.get('workflow_state') or ''
    if ws == 'Approved':
      supplier = doc.get('custom_auto_po_supplier')
      if not supplier:
        frappe.throw('Auto Create Purchase Order is enabled: please set Auto PO Supplier on this Material Request before submit')
      po_items = []
      if doc.get('items'):
        for it in doc.get('items'):
          qty_val = it.get('qty') or it.get('required_qty') or 0
          po_items.append({
            'doctype': 'Purchase Order Item',
            'item_code': it.get('item_code'),
            'qty': qty_val,
            'rate': 0.0,
            'schedule_date': doc.get('schedule_date'),
            'material_request': doc.name,
            'material_request_item': it.get('name')
          })
      try:
        po = frappe.get_doc({
          'doctype': 'Purchase Order',
          'supplier': supplier,
          'transaction_date': frappe.utils.nowdate(),
          'schedule_date': doc.get('schedule_date') or frappe.utils.nowdate(),
          'company': doc.get('company'),
          'items': po_items,
          'custom_order_category': doc.get('custom_order_category')
        })
        po.insert()
        frappe.get_doc({'doctype': 'Comment', 'reference_doctype': 'Material Request', 'reference_name': doc.name, 'content': 'Draft Purchase Order ' + po.name + ' created automatically.'}).insert()
      except Exception as e:
        frappe.get_doc({'doctype': 'Comment', 'reference_doctype': 'Material Request', 'reference_name': doc.name, 'content': 'Auto PO creation skipped due to validation: ' + str(e)}).insert()

MAX_QTY_CHECK = 99999999
MIN_QTY_CHECK = 0
if doc.items:
    wh = None
    if doc.get('set_warehouse'):
        wh = doc.set_warehouse
    if not wh and doc.items and doc.items[0].get('warehouse'):
        wh = doc.items[0].warehouse
    if wh:
        min_val = frappe.db.get_value('Warehouse', wh, 'custom_min_order_qty')
        max_val = frappe.db.get_value('Warehouse', wh, 'custom_max_order_qty')
        try:
            min_val = float(min_val) if min_val not in (None, '') else None
        except Exception:
            min_val = None
        try:
            max_val = float(max_val) if max_val not in (None, '') else None
        except Exception:
            max_val = None
        total_qty = 0.0
        for row in doc.items:
            qty = row.get('qty') or 0
            try:
                total_qty = total_qty + float(qty)
            except Exception:
                total_qty = total_qty + 0.0
        if min_val is not None and total_qty < min_val:
            frappe.throw('Material Request total qty (' + str(total_qty) + ') is less than the warehouse minimum order quantity (' + str(min_val) + ').')
        if max_val is not None and total_qty > max_val:
            frappe.throw('Material Request total qty (' + str(total_qty) + ') exceeds the warehouse maximum order quantity (' + str(max_val) + ').')
    else:
        pass

if doc.get('items'):
	for row in doc.items:
		item_code = row.item_code
		dest_wh = None
		if row.get('t_warehouse'):
			dest_wh = row.get('t_warehouse')
		elif doc.get('to_warehouse'):
			dest_wh = doc.get('to_warehouse')
		if item_code and dest_wh:
			item_req = frappe.db.get_value('Item', item_code, 'custom_storage_requirement')
			wh_type = frappe.db.get_value('Warehouse', dest_wh, 'custom_storage_type')
			if item_req and wh_type and item_req != wh_type:
				frappe.throw('Storage mismatch for Item ' + str(item_code) + ': requires ' + str(item_req) + ' storage but target Warehouse ' + str(dest_wh) + ' is ' + str(wh_type) + '.')

if doc.get('items'):
	for row in doc.items:
		item_code = row.item_code
		wh = row.get('warehouse')
		if item_code and wh:
			item_req = frappe.db.get_value('Item', item_code, 'custom_storage_requirement')
			wh_type = frappe.db.get_value('Warehouse', wh, 'custom_storage_type')
			if item_req and wh_type and item_req != wh_type:
				frappe.throw('Storage mismatch for Item ' + str(item_code) + ': requires ' + str(item_req) + ' storage but Warehouse ' + str(wh) + ' is ' + str(wh_type) + '.')

if doc.get('custom_demand_cycle') == 'QD':
    if not doc.get('custom_qd_number'):
        frappe.throw('QD Number is required when Demand Cycle is QD.')
    if not doc.get('custom_qd_release_date'):
        frappe.throw('QD Release Date is required when Demand Cycle is QD.')

AMOUNT_FIELD = 'custom_urc_credit_amount'
if doc.get(AMOUNT_FIELD) and frappe.utils.flt(doc.get(AMOUNT_FIELD)) > 0:
    if doc.get('custom_urc_credit_posted') == 1:
        pass
    else:
        comp = frappe.db.get_value('Company', doc.company, ['custom_urc_payables_account', 'custom_urc_clearing_account'], as_dict=1)
        if not comp or not comp.get('custom_urc_payables_account') or not comp.get('custom_urc_clearing_account'):
            frappe.throw('Company URC accounts are not set. Please set URC Payables Account and URC Clearing Account on Company ' + str(doc.company))
        amount = frappe.utils.flt(doc.get(AMOUNT_FIELD))
        posting_date = doc.get('transaction_date') or frappe.utils.nowdate()
        je = frappe.get_doc({
            'doctype': 'Journal Entry',
            'voucher_type': 'Journal Entry',
            'company': doc.company,
            'posting_date': posting_date,
            'user_remark': 'URC Credit for Material Request ' + str(doc.name)
        })
        je.append('accounts', {
            'account': comp.get('custom_urc_clearing_account'),
            'debit_in_account_currency': amount
        })
        je.append('accounts', {
            'account': comp.get('custom_urc_payables_account'),
            'credit_in_account_currency': amount
        })
        je.insert()
        je.submit()
        frappe.db.set_value('Material Request', doc.name, 'custom_urc_credit_reference', je.name)
        frappe.db.set_value('Material Request', doc.name, 'custom_urc_credit_posted', 1)

ALLOWED_MR_TYPE = "Material Issue"

if doc.material_request_type == ALLOWED_MR_TYPE:
    # Basic presence checks
    if not doc.get("customer"):
        frappe.throw("Customer is required for beneficiary quota validation.")
    rank = ""
    if doc.get("custom_beneficiary_rank"):
        rank = str(doc.get("custom_beneficiary_rank")).strip()
    designation = doc.get("custom_beneficiary_designation")
    if not rank or not designation:
        frappe.throw("Beneficiary Rank and Beneficiary Designation are required for quota validation.")

    # Build current request quantities by item group
    current_by_group = {}
    for it in (doc.get("items") or []):
        ig = frappe.db.get_value("Item", it.get("item_code"), "item_group")
        if ig:
            qty = frappe.utils.flt(it.get("qty"))
            current_by_group[ig] = current_by_group.get(ig, 0) + qty

    # Determine current month range
    tx = doc.get("transaction_date")
    if not tx:
        tx = frappe.utils.nowdate()
    d = frappe.utils.getdate(str(tx))
    month_start = d.replace(day=1)
    next_month = frappe.utils.add_months(month_start, 1)
    month_end = frappe.utils.add_days(next_month, -1)

    # Sum historical submitted MR quantities for the same customer in the same month
    total_by_group = {}
    names = frappe.db.get_all(
        "Material Request",
        filters={
            "docstatus": 1,
            "customer": doc.get("customer"),
            "material_request_type": ALLOWED_MR_TYPE,
            "transaction_date": ["between", [str(month_start), str(month_end)]]
        },
        fields=["name"]
    )
    for n in names:
        rows = frappe.db.get_all(
            "Material Request Item",
            filters={"parent": n.get("name")},
            fields=["item_code", "qty"]
        )
        for r in rows:
            ig = frappe.db.get_value("Item", r.get("item_code"), "item_group")
            if ig:
                total_by_group[ig] = total_by_group.get(ig, 0) + frappe.utils.flt(r.get("qty"))

    # Add current request quantities
    for ig in current_by_group:
        total_by_group[ig] = total_by_group.get(ig, 0) + current_by_group.get(ig, 0)

    # Validate against Beneficiary Quota Rule per item group
    for ig in total_by_group:
        rules = frappe.db.get_all(
            "Beneficiary Quota Rule",
            filters={
                "designation": designation,
                "rank": rank,
                "item_group": ig
            },
            fields=["monthly_quota_qty"],
            limit=1
        )
        if rules and len(rules) > 0:
            allowed = frappe.utils.flt(rules[0].get("monthly_quota_qty"))
            consumed = frappe.utils.flt(total_by_group.get(ig, 0))
            if consumed > allowed:
                msg = "Monthly quota exceeded for Item Group '" + str(ig) + "'. Allowed: " + str(allowed) + ", Requested this month (incl. current): " + str(consumed)
                frappe.throw(msg)
        else:
            # No rule -> allow (assumption). If required, change policy to hard block.
            pass
else:
    # Not a beneficiary issue; no quota enforcement
    pass

if doc.get('custom_workflow_state') in (None, ''):
    frappe.throw('Consolidated Demand must have Workflow State set before submit')
# enforce that RM approver is set before submitting to HO state
if doc.get('custom_workflow_state') and 'HO' in doc.get('custom_workflow_state'):
    if not doc.get('custom_rm_approver'):
