COMPANY_CREDIT_ACCOUNT_FIELD = "custom_urc_temp_credit_account"
COMPANY_RECEIVABLE_ACCOUNT_FIELD = "custom_urc_receivable_account"


def get_company_account(company, fieldname):
    val = frappe.db.get_value("Company", company, fieldname)
    return val


def get_cds_to_process(today):
    cds = frappe.get_all(
        "Consolidated Demand",
        filters={
            "period_end": ["<=", str(today)],
            "custom_credit_revoked": ["!=", 1]
        },
        fields=["name", "company", "period_start", "period_end"]
    )
    return cds


def main():
    today = frappe.utils.getdate()
    cds = get_cds_to_process(today)
    for cd in cds:
        groups = {}
        mrs = frappe.get_all(
            "Material Request",
            filters=[
                ["Material Request", "transaction_date", ">=", cd.get("period_start")],
                ["Material Request", "transaction_date", "<=", cd.get("period_end")],
                ["Material Request", "custom_urc_credit_posted", "=", 1],
                ["Material Request", "custom_urc_credit_amount", ">", 0],
                ["Material Request", "custom_urc_credit_revoked", "!=", 1]
            ],
            fields=["name", "company", "customer", "custom_urc_credit_amount"]
        )
        for r in mrs:
            company = r.get("company")
            customer = r.get("customer") or ""
            key = company + "||" + customer
            if not groups.get(key):
                groups[key] = {"company": company, "customer": customer, "total": 0.0, "mrs": []}
            amt = frappe.utils.flt(r.get("custom_urc_credit_amount"))
            groups[key]["total"] = groups[key]["total"] + amt
            groups[key]["mrs"].append(r.get("name"))
        for key in groups:
            g = groups.get(key)
            if not g:
                continue
            if not g.get("customer"):
                continue
            temp_acc = get_company_account(g.get("company"), COMPANY_CREDIT_ACCOUNT_FIELD)
            recv_acc = get_company_account(g.get("company"), COMPANY_RECEIVABLE_ACCOUNT_FIELD)
            if not temp_acc or not recv_acc:
                continue
            total_amt = frappe.utils.flt(g.get("total"))
            if total_amt <= 0:
                continue
            je = frappe.get_doc({
                "doctype": "Journal Entry",
                "posting_date": str(today),
                "company": g.get("company"),
                "user_remark": "URC Temporary Credit Reversal for " + g.get("customer") + " in cycle " + cd.get("name")
            })
            je.append("accounts", {
                "account": temp_acc,
                "debit_in_account_currency": total_amt
            })
            je.append("accounts", {
                "account": recv_acc,
                "credit_in_account_currency": total_amt,
                "party_type": "Customer",
                "party": g.get("customer")
            })
            je.insert()
            if je.docstatus == 0:
                je.submit()
            for mr_name in g.get("mrs"):
                mr = frappe.get_doc("Material Request", mr_name)
                mr.custom_urc_credit_revoked = 1
                mr.custom_urc_credit_revoked_on = str(today)
                mr.custom_urc_credit_reversal_reference = je.name
                mr.save()
        cd_doc = frappe.get_doc("Consolidated Demand", cd.get("name"))
        cd_doc.custom_credit_revoked = 1
        cd_doc.custom_credit_revoked_on = str(today)
        cd_doc.save()

main()

