# define period references (use current month as forecast month; average over last N complete months)
today = frappe.utils.getdate(frappe.utils.nowdate())
current_first = today.replace(day=1)
prev_first = frappe.utils.add_months(current_first, -1)
forecast_month = current_first

# collect Liquor items (by Item Group)
liquor_items = frappe.get_all('Item', filters={'item_group': 'Liquor'}, fields=['name'])
items_map = {}
for it in liquor_items:
    nm = it.get('name')
    if nm:
        items_map[nm] = 1

if len(items_map) > 0 and months > 0:
    totals = {}
    idx = 0
    while idx < months:
        m_first = frappe.utils.add_months(prev_first, -idx)
        m_second = frappe.utils.add_months(m_first, 1)
        m_end = frappe.utils.add_days(m_second, -1)
        invs = frappe.get_all('Sales Invoice', filters={'docstatus': 1, 'posting_date': ['between', [m_first, m_end]]}, fields=['name'])
        inv_names = []
        for inv in invs:
            inv_names.append(inv.get('name'))
        if len(inv_names) > 0:
            rows = frappe.get_all('Sales Invoice Item', filters={'parent': ['in', inv_names]}, fields=['item_code', 'qty'])
            for r in rows:
                code = r.get('item_code')
                if code and (code in items_map):
                    q = r.get('qty') or 0
                    if not (code in totals):
                        totals[code] = {}
                    existing = 0
                    if idx in totals[code]:
                        existing = totals[code][idx]
                    totals[code][idx] = existing + q
        idx = idx + 1

    for code in totals:
        s = 0.0
        j = 0
        while j < months:
            part = 0.0
            if j in totals[code]:
                val = totals[code][j]
                if val:
                    part = float(val)
            s = s + part
            j = j + 1
        avg = 0.0
        if months > 0:
            avg = s / float(months)
        if avg > 0:
            existing = frappe.get_all('Liquor Demand Forecast', filters={'item': code, 'month': forecast_month}, fields=['name'])
            if len(existing) > 0:
                docname = existing[0].get('name')
                if docname:
                    d = frappe.get_doc('Liquor Demand Forecast', docname)
                    d.forecast_qty = avg
                    d.save()
            else:
                d = frappe.get_doc({'doctype': 'Liquor Demand Forecast', 'item': code, 'month': forecast_month, 'forecast_qty': avg})
                d.insert()

